    class t_Spirit_ExpUpgrade extends BaseCfg {
        static get Ins() {
            if (!this._ins) {
                this._ins = new t_Spirit_ExpUpgrade();
            }
            return this._ins;
        }
        GetTabelName() {
            return "t_Spirit_ExpUpgrade";
        }
        getCfgByLv(lv) {
            let l = this.List;
            for (let i = 0; i < l.length; i++) {
                let cfg = l[i];
                if (cfg.f_SpiritID == lv) {
                    return cfg;
                }
            }
        }
        isFull(lv, qua) {
            let cfg = this.getCfgByLv(lv);
            return cfg[`f_Quality${qua}`] == 0;
        }
        getMaxExp(lv, qua) {
            let l = this.List;
            let val = 0;
            for (let i = 0; i < l.length; i++) {
                let cfg = l[i];
                if (cfg.f_SpiritID <= lv) {
                    val += cfg[`f_Quality${qua}`];
                }
                else {
                    break;
                }
            }
            return val;
        }
        getMinExp(lv, qua) {
            let l = this.List;
            let val = 0;
            for (let i = 0; i < l.length; i++) {
                let cfg = l[i];
                if (cfg.f_SpiritID < lv) {
                    val += cfg[`f_Quality${qua}`];
                }
                else {
                    break;
                }
            }
            return val;
        }
        getMaxByQua(qua) {
            let l = this.List;
            let val = 0;
            for (let i = 0; i < l.length; i++) {
                let cfg = l[i];
                let quaVal = parseInt(cfg[`f_Quality${qua}`]);
                val += quaVal;
            }
            return val;
        }
        getLvByExp(qua, exp) {
            let l = this.List;
            let v = 0;
            let lv = 0;
            for (let i = 0; i < l.length; i++) {
                let cfg = l[i];
                let addExp = parseInt(cfg[`f_Quality${qua}`]);
                if (addExp) {
                    if (exp >= v && exp < v + addExp) {
                        return cfg.f_SpiritID;
                    }
                    v += addExp;
                    lv = cfg.f_SpiritID;
                }
            }
            return lv + 1;
        }
    }
