    class ZuoqiBackView extends ViewBase {
        constructor() {
            super(...arguments);
            this.mMask = true;
        }
        onAddLoadRes() {
            this.addAtlas("zuoqi.atlas");
        }
        onExit() { }
        onFirstInit() {
            if (!this._ui) {
                this.model = ZuoQiModel.Ins;
                this.UI = this._ui = new ui.views.zuoqi.ui_zuoqi_back_viewUI();
                this.bindClose(this._ui.close1);
                this.slotView = new ZuoQiSlotView(this._ui.slot0);
                ButtonCtl.CreateBtn(this._ui.washBtn, this, this.onWashHandler);
                ButtonCtl.CreateBtn(this._ui.canelBtn, this, this.Close);
            }
        }
        onWashHandler() {
            if (this.cfg) {
                if (MainModel.Ins.isItemEnoughSt(this.cfg.f_Ruturn, true)) {
                    this.model.once(ZuoQiEvent.ReturnMountSucceed, this, this.Close);
                    let req = new MountReturn_req();
                    req.id = this._zqVo.rideId;
                    SocketMgr.Ins.SendMessageBin(req);
                }
            }
        }
        onInit() {
            this._zqVo = this.Data;
            this.slotView.setData(this._zqVo);
            this._ui.nameTf.text = this._zqVo.getName();
            this._ui.nameTf.color = this._zqVo.getQuaColor();
            let qua = this._zqVo.quality;
            let cfg = MountConfigProxy.Ins.getByQualityID(qua);
            this.cfg = cfg;
            if (cfg) {
                let _itemVo = ItemViewFactory.convertItem(cfg.f_Ruturn);
                this._ui.goldicon.skin = _itemVo.getIcon();
                this._ui.goldTf.text = StringUtil.val2m(_itemVo.count);
            }
            this.model.once(ZuoQiEvent.ReturnPreView, this, this.showAttr);
            let req = new MountReturnPreView_req();
            req.id = this._zqVo.rideId;
            SocketMgr.Ins.SendMessageBin(req);
        }
        showAttr() {
            let _list1 = this.model.preRewardList;
            this._ui.icon2.visible = false;
            this._ui.tf2.visible = false;
            this._ui.icon4.visible = this._ui.tf4.visible = false;
            this._ui.icon1.skin = IconUtils.getIconByCfgId(_list1[0].id);
            this._ui.tf1.text = StringUtil.val2m(_list1[0].count);
            if (_list1.length > 1) {
                this._ui.icon2.visible = true;
                this._ui.tf2.visible = true;
                this._ui.icon2.skin = IconUtils.getIconByCfgId(_list1[1].id);
                this._ui.tf2.text = StringUtil.val2m(_list1[1].count);
                let _item2 = _list1[2];
                if (_item2) {
                    this._ui.icon4.visible = this._ui.tf4.visible = true;
                    this._ui.icon4.skin = IconUtils.getIconByCfgId(_item2.id);
                    this._ui.tf4.text = StringUtil.val2m(_item2.count);
                }
            }
            this.layoutView(_list1.length);
        }
        layoutView(itemCount) {
            let w = this._ui.icon1.width + this._ui.tf1.textField.width + this._ui.tf0.textField.width;
            if (itemCount > 1) {
                w += this._ui.icon2.width + this._ui.tf2.textField.width;
            }
            if (this._ui.icon4.visible) {
                w += this._ui.tf4.textField.width + this._ui.icon4.width;
            }
            let ox = (this._ui.width - w) / 2;
            this._ui.tf0.x = ox;
            this._ui.icon1.x = this._ui.tf0.x + this._ui.tf0.textField.width;
            this._ui.tf1.x = this._ui.icon1.x + this._ui.icon1.width;
            this._ui.icon2.x = this._ui.tf1.x + this._ui.tf1.textField.width;
            this._ui.tf2.x = this._ui.icon2.x + this._ui.icon2.width;
            this._ui.icon4.x = this._ui.tf2.x + this._ui.tf2.textField.width;
            this._ui.tf4.x = this._ui.icon4.x + this._ui.icon4.width;
        }
    }

    class ZuoQiBuyShopView extends ViewBase {
        constructor() {
            super(...arguments);
            this.mMask = true;
            this.mMainSnapshot = true;
            this.autoFree = true;
        }
        onAddLoadRes() {
            this.addAtlas("zuoqi.atlas");
        }
        onFirstInit() {
            if (!this.UI) {
                if (!this.UI) {
                    this.UI = this._ui = new ui.views.zuoqi.ui_zuoqiGMViewUI;
                    this.bindClose(this._ui.close1);
                    this.btnList.push(ButtonCtl.Create(this._ui.btn_sub, new Laya.Handler(this, this.onBtnSubClick)), ButtonCtl.Create(this._ui.btn_sub1, new Laya.Handler(this, this.onBtnSub1Click)), ButtonCtl.Create(this._ui.btn_sub2, new Laya.Handler(this, this.onBtnSub2Click)), ButtonCtl.Create(this._ui.btn_add, new Laya.Handler(this, this.onBtnAddClick)), ButtonCtl.Create(this._ui.btn_add1, new Laya.Handler(this, this.onBtnAdd1Click)), ButtonCtl.Create(this._ui.btn_add2, new Laya.Handler(this, this.onBtnAdd2Click)), ButtonCtl.Create(this._ui.btn_qx, new Laya.Handler(this, this.onBtnQXClick)), ButtonCtl.Create(this._ui.btn_qd, new Laya.Handler(this, this.onBtnQDClick)));
                }
            }
        }
        onInit() {
            this._data = this.Data;
            if (this._data.f_BuyLimit) {
                let vo = ZuoQiModel.Ins.shopList.find(ele => ele.id == this._data.f_id);
                this._max = this._data.f_BuyLimit - vo.cnt;
            }
            else {
                this._max = 9999;
            }
            this._num = 1;
            this.updataView();
        }
        onExit() {
        }
        onBtnSubClick() {
            this._num--;
            this.setBtn();
        }
        onBtnSub1Click() {
            this._num -= 10;
            this.setBtn();
        }
        onBtnSub2Click() {
            this._num -= 100;
            this.setBtn();
        }
        onBtnAddClick() {
            this._num++;
            this.setBtn();
        }
        onBtnAdd1Click() {
            this._num += 10;
            this.setBtn();
        }
        onBtnAdd2Click() {
            this._num += 100;
            this.setBtn();
        }
        onBtnQXClick() {
            this.Close();
        }
        onBtnQDClick() {
            if (this._data) {
                let req = new MountShop_req;
                req.id = this._data.f_id;
                req.cnt = this._num;
                SocketMgr.Ins.SendMessageBin(req);
            }
        }
        updataView() {
            let itemVo = new ItemVo();
            let arr = this._data.f_goods.split("-");
            itemVo.cfgId = parseInt(arr[0]);
            itemVo.count = parseInt(arr[1]);
            ItemViewFactory.refreshSlot(this._ui.item, itemVo);
            this._ui.lab_title.text = itemVo.getName();
            this.setBtn();
        }
        setBtn() {
            if (this._num <= 1) {
                this._ui.btn_sub.disabled = true;
            }
            else {
                this._ui.btn_sub.disabled = false;
            }
            if (this._num <= 10) {
                this._ui.btn_sub1.disabled = true;
            }
            else {
                this._ui.btn_sub1.disabled = false;
            }
            if (this._num <= 100) {
                this._ui.btn_sub2.disabled = true;
            }
            else {
                this._ui.btn_sub2.disabled = false;
            }
            if (this._num >= this._max) {
                this._ui.btn_add.disabled = true;
            }
            else {
                this._ui.btn_add.disabled = false;
            }
            if (this._max - this._num < 10) {
                this._ui.btn_add1.disabled = true;
            }
            else {
                this._ui.btn_add1.disabled = false;
            }
            if (this._max - this._num < 100) {
                this._ui.btn_add2.disabled = true;
            }
            else {
                this._ui.btn_add2.disabled = false;
            }
            this._ui.lab_num.text = this._num + "";
            let arr = this._data.f_Price.split("-");
            let id = parseInt(arr[0]);
            let num = parseInt(arr[1]);
            let needC = num * this._num;
            let count = MainModel.Ins.mRoleData.getVal(id);
            this._ui.icon.skin = IconUtils.getIconByCfgId(id);
            this._ui.lab_m.text = needC + "";
            this._ui.lab_d.x = this._ui.lab_m.x + this._ui.lab_m.textField.width;
            let arr1 = this._data.f_goods.split("-");
            let idd = parseInt(arr1[0]);
            this._ui.lab_d.text = " 购买" + IconUtils.getNameByID(idd);
            if (count >= needC) {
                this._ui.lab_m.color = "#54e80d";
            }
            else {
                this._ui.lab_m.color = "#ff1e00";
            }
        }
    }

