    class ZuoQiLvResult {
        constructor() {
            this.status = ZuoQiLvResult.NORMAL;
        }
        parse(need, itemid) {
            let have = MainModel.Ins.mRoleData.getVal(itemid);
            this.needItemid = itemid;
            this.need = need;
            this.have = have;
            if (need > have) {
                this.status = ZuoQiLvResult.NOT_ENOUGH;
            }
        }
    }
    ZuoQiLvResult.MAX = 1;
    ZuoQiLvResult.NOT_ENOUGH = 2;
