    class t_Item_Guide extends BaseCfg {
        constructor() {
            super();
            this.rebuild();
        }
        GetTabelName() {
            return "t_Item_Guide";
        }
        static get Ins() {
            if (!this._ins) {
                this._ins = new t_Item_Guide();
            }
            return this._ins;
        }
        rebuild() {
            this.typeList = [];
            this.itemList = [];
            let l = this.List;
            for (let i = 0; i < l.length; i++) {
                let cfg = l[i];
                let id = parseInt(cfg.f_GuidePosition.split("-")[0]);
                if (this.typeList.indexOf(id) == -1) {
                    this.typeList.push(id);
                }
                let itemId = cfg.f_ItemID;
                if (!this.itemList[itemId]) {
                    this.itemList[itemId] = [];
                }
                this.itemList[itemId].push(cfg);
            }
        }
    }

