    class DouYinButton extends BaseButton {
        constructor(o, that, func) {
            super();
            this.that = that;
            this.func = func;
            let curThat = this;
            let t = 1;
            let params = {
                type: "image",
                image: maskImgURL(),
                style: {
                    left: o.x * t,
                    top: o.y * t,
                    width: o.w * t,
                    height: o.h * t,
                    borderColor: "#ffffff00",
                    backgroundColor: "#ffffff00",
                    borderRadius: 0,
                    borderWidth: 0
                },
                success(button) {
                    function button_tap(res) {
                        curThat.clickRun();
                    }
                    if (typeof button.onTap == "function") {
                        button.onTap(button_tap);
                    }
                    curThat.btnAuthorize = button;
                    curThat.updateView();
                },
                fail(res) {
                    console.log("创建失败", res.errMsg);
                },
            };
            this.createBtn(params);
        }
        createBtn(params) {
            gameTT.createInteractiveButton(params);
        }
        clickRun() {
        }
        updateView() {
            if (this._isShow) {
                this.show();
            }
            else {
                this.hide();
            }
        }
    }
