    class NewShopStyle extends Laya.Script {
        constructor() {
            super(...arguments);
            this.offsetCount = 10;
        }
        setItemData(itemVo, target) {
            this.targetVo = target;
            this.itemVo = itemVo;
        }
        get selCount() {
            return this._num;
        }
        onAwake() {
            this._ui = this.owner;
            this.btn_sub = ButtonCtl.Create(this._ui.btn_sub, new Laya.Handler(this, this.onBtnSubClick));
            this.btn_sub1 = ButtonCtl.Create(this._ui.btn_sub1, new Laya.Handler(this, this.onBtnSub1Click));
            this.btn_add = ButtonCtl.Create(this._ui.btn_add, new Laya.Handler(this, this.onBtnAddClick));
            this.btn_add1 = ButtonCtl.Create(this._ui.btn_add1, new Laya.Handler(this, this.onBtnAdd1Click));
            MainModel.Ins.on(MainEvent.ValChangeCell, this, this.onValChangeCell);
            this._num = 1;
            this.setBtn();
        }
        onValChangeCell(id) {
            if (this.targetVo && id == this.targetVo.cfgId) {
                this.setBtn();
            }
        }
        onBtnAdd1Click() {
            this._num += this.offsetCount;
            this.setBtn();
        }
        onDestroy() {
            MainModel.Ins.off(MainEvent.ValChangeCell, this, this.onValChangeCell);
            this.btn_sub.dispose();
            this.btn_sub1.dispose();
            this.btn_add.dispose();
            this.btn_add1.dispose();
            this.itemVo = null;
            this._ui = null;
        }
        onBtnSubClick() {
            this._num--;
            this.setBtn();
        }
        onBtnSub1Click() {
            this._num -= this.offsetCount;
            this.setBtn();
        }
        onBtnAddClick() {
            this._num++;
            this.setBtn();
        }
        setBtn() {
            if (this._num <= 1) {
                this.btn_sub.grayMouseDisable = true;
                this.btn_sub1.grayMouseDisable = true;
            }
            else {
                this.btn_sub.grayMouseDisable = false;
                this.btn_sub1.grayMouseDisable = false;
            }
            this._ui.lab_num.text = this._num + "";
            let id = this.itemVo.cfgId;
            let num = this.itemVo.count;
            let needC = num * this._num;
            let count = MainModel.Ins.mRoleData.getVal(id);
            this._ui.icon.skin = IconUtils.getIconByCfgId(id);
            this._ui.lab_m.text = `${needC}/${count}`;
            this._ui.lab_d.x = this._ui.lab_m.x + this._ui.lab_m.textField.width;
            this._ui.lab_d.text = `${E.getLang("buy")}${this.targetVo.getName()}`;
            if (count >= needC) {
                this._ui.lab_m.color = "#54e80d";
            }
            else {
                this._ui.lab_m.color = "#ff1e00";
            }
        }
    }

    class ShopBuyView extends ViewBase {
        constructor() {
            super(...arguments);
            this.mMask = true;
            this.autoFree = true;
        }
        onAddLoadRes() { }
        onExit() {
            if (this.newShopStyle) {
                this.newShopStyle.destroy();
                this.newShopStyle = null;
            }
        }
        get selCount() {
            return this.newShopStyle ? this.newShopStyle.selCount : 1;
        }
        onFirstInit() {
            if (!this.UI) {
                this.UI = this._ui = new ui.views.main.ui_shopBuyViewUI();
                this.bindClose(this._ui.closeBtn1);
                ButtonCtl.Create(this._ui.cancelBtn, new Laya.Handler(this, this.onCancelHandler));
                ButtonCtl.Create(this._ui.okBtn, new Laya.Handler(this, this.onOkHandler));
            }
        }
        onOkHandler() {
            this._data.ok.runWith([this._data]);
            if (!this._data.buyEndNotClose) {
                this.Close();
            }
        }
        onCancelHandler() {
            this.Close();
        }
        clearUI() {
            this._ui.item.tf1.text = "";
            this._ui.item.quality.skin = IconUtils.defaultIcon;
            this._ui.item.icon.skin = "";
            this._ui.nameTF.text = "";
            this._ui.moneyTf.text = "";
            this._ui.goldIcon.skin = "";
        }
        refreshItem(_vo) {
            let targetCfg = ItemProxy.Ins.getCfg(_vo.targetId);
            this._ui.nameTF.text = main.itemName(targetCfg.f_name);
            let _itemVo = new ItemVo();
            _itemVo.cfgId = _vo.targetId;
            _itemVo.count = _vo.targetCount;
            ItemViewFactory.refreshSlot(this._ui.item, _itemVo);
            return _itemVo;
        }
        onInit() {
            this.clearUI();
            this._data = this.Data;
            let _vo = this.Data;
            this._ui.oldStyles.visible = false;
            this._ui.newStyles.visible = false;
            this._ui.item.offAll();
            switch (_vo.type) {
                case EBuyType.HotItem:
                    {
                        let _itemVo = this.refreshItem(_vo);
                        this.newShopStyle = this._ui.addComponent(NewShopStyle);
                        this.newShopStyle.setItemData(ItemViewFactory.convertItem(`${_vo.needItemId}-${_vo.needCount}`), _itemVo);
                        this._ui.newStyles.visible = true;
                    }
                    break;
                case EBuyType.Item:
                    {
                        this._ui.oldStyles.visible = true;
                        let _itemVo = this.refreshItem(_vo);
                        this._ui.descTf.text = _itemVo.getDesc();
                    }
                    break;
                case EBuyType.LabourShop:
                    this._ui.oldStyles.visible = true;
                    this.refreshLabourShop(_vo);
                    break;
                default:
                    E.ViewMgr.ShowMsgBox(EMsgBoxType.OnlyOk, "you must be set type!");
                    break;
            }
            this._ui.goldIcon.skin = IconUtils.getIconByCfgId(_vo.needItemId);
            this._ui.moneyTf.text = StringUtil.val2m(_vo.needCount);
        }
        refreshLabourShop(_vo) {
            let cfg = t_Labour_Shop.Ins.GetDataById(_vo.targetId);
            switch (cfg.f_GoodsType) {
                case ELabodayType.EquipStyle:
                    let arr1 = cfg.f_GoodsID.split("-");
                    let part = parseInt(arr1[0]);
                    let style = parseInt(arr1[1]);
                    this._ui.item.tf1.text = "1";
                    this._ui.item.icon.skin = ItemViewFactory.getEquipIcon(part, style);
                    this._ui.item.quality.skin = IconUtils.getQuaIcon(cfg.f_GoodsQua);
                    let nameArr = cfg.f_Tips.split("-");
                    if (nameArr.length >= 2) {
                        this._ui.nameTF.text = nameArr[0];
                        this._ui.descTf.text = nameArr[1];
                    }
                    break;
                case ELabodayType.Item:
                    let itemVo = ItemViewFactory.convertItem(cfg.f_GoodsID);
                    this._ui.item.icon.skin = IconUtils.getIconByCfgId(itemVo.cfgId);
                    this._ui.item.tf1.text = itemVo.count.toString();
                    this._ui.item.quality.skin = IconUtils.getQuaIcon(itemVo.cfg.f_qua);
                    this._ui.nameTF.text = itemVo.getName();
                    this._ui.descTf.text = itemVo.getDesc();
                    break;
            }
        }
    }

