        funcSetRed(fid, v) {
            let cfg = FuncProxy.Ins.getCfgByFid(fid);
            if (!cfg) {
                LogSys$1.Error(`not find funId:${fid}`);
                return;
            }
            if (v && cfg.f_close) {
                v = false;
            }
            let status = false;
            if (v) {
                let index = this.redList.indexOf(fid);
                if (index == -1) {
                    this.redList.push(fid);
                    status = true;
                }
            }
            else {
                let index = this.redList.indexOf(fid);
                if (index != -1) {
                    this.delRed(fid);
                    status = true;
                }
            }
            if (E.ViewMgr.isOpenReg(EViewType.FightMain)) {
                return;
            }
            this.event(MainEvent.FuncSmallIconUpdate);
        }
