        isNeePop(_getEquip) {
            let boxAutoVo = this.boxAutoVo;
            let plusStop = false;
            let attrStop = false;
            let quaStop = false;
            let plusStopNeed = false;
            let attrStopNeed = false;
            if (boxAutoVo.isOpen) {
                let curWearvo = this.getEquipWearVo(_getEquip.type);
                if (boxAutoVo.mCheckPlusHigh) {
                    plusStopNeed = true;
                    if (curWearvo && _getEquip.plus > curWearvo.plus) {
                        plusStop = true;
                    }
                }
                let attrs = [];
                attrs = attrs.concat(_getEquip.attrList);
                attrs = attrs.concat(_getEquip.attrList1);
                if (boxAutoVo.attrCk) {
                    attrStopNeed = true;
                    if (boxAutoVo.checkAttrIsCanStop(attrs)) {
                        attrStop = true;
                    }
                }
            }
            if (_getEquip.quality >= this.quickCfg.f_id) {
                quaStop = true;
            }
            let blist = [];
            if (attrStopNeed) {
                blist.push(attrStop);
            }
            if (plusStopNeed) {
                blist.push(plusStop);
            }
            blist.push(quaStop);
            let needPop = this.getNeedStop(boxAutoVo.togetherCkVal, blist);
            return needPop;
        }
