    class t_Box_AnimationRate extends BaseCfg {
        GetTabelName() {
            return "t_Box_AnimationRate";
        }
        static get Ins() {
            if (!this._ins) {
                this._ins = new t_Box_AnimationRate();
            }
            return this._ins;
        }
        getRandomVal() {
            if (!this._dataList) {
                this._dataList = [];
                let l = this.List;
                let v = 0;
                for (let i = 0; i < l.length; i++) {
                    let cfg = l[i];
                    let pre = l[i - 1];
                    let old = v;
                    v += cfg.f_animRate;
                    let vo = new t_BoxRangle();
                    if (!pre) {
                        vo.start = old;
                        vo.end = v - 1;
                    }
                    else {
                        vo.start = old;
                        if (i < l.length - 1) {
                            vo.end = v - 1;
                        }
                        else {
                            vo.end = v;
                        }
                    }
                    this._dataList.push(vo);
                }
            }
            let val = Math.random() * 10000;
            let index = 0;
            for (let i = 0; i < this._dataList.length; i++) {
                let vo = this._dataList[i];
                if (val >= vo.start && val < vo.end) {
                    index = i;
                }
            }
            let cfg = this.List[index];
            return cfg.f_animindex;
        }
    }
