            if (this._index >= FuJiangDrawExpProxy.Ins.List.length - 1) {
                this._index = FuJiangDrawExpProxy.Ins.List.length - 1;
                this._ui.btn_r.visible = false;
            }
            else {
                this._ui.btn_r.visible = true;
            }
