    function getQua(vo) {
        return Mount_ListProxy.Ins.getCfg(vo.id).f_Quality;
    }
    class ZuoqiFactory {
        static createZuoQiVo(cell) {
            let _vo = new ZuoqiVo();
            _vo.curVo = cell;
            return _vo;
        }
        static sortStar(a, b) {
            if (a.star > b.star) {
                return -1;
            }
            else if (a.star < b.star) {
                return 1;
            }
            return 0;
        }
        static sortLv(a, b) {
            if (a.lv > b.lv) {
                return -1;
            }
            else if (a.lv < b.lv) {
                return 1;
            }
            return 0;
        }
        static sortQua(a, b) {
            let aq = ZuoqiFactory.getQua(a);
            let bq = ZuoqiFactory.getQua(b);
            if (aq > bq) {
                return -1;
            }
            else if (aq < bq) {
                return 1;
            }
            return 0;
        }
        static getQua(vo) {
            return Mount_ListProxy.Ins.getCfg(vo.id).f_Quality;
        }
        static sortLvStarFunc(a, b) {
            if (a.lv > b.lv) {
                if (a.star < b.star) {
                    return 1;
                }
                return -1;
            }
            else if (a.lv < b.lv) {
                if (a.star > b.star) {
                    return -1;
                }
                return 1;
            }
            return 0;
        }
        static sortList(l) {
            l = l.sort(this.sortQua);
            let quaMap = {};
            for (let i = 0; i < l.length; i++) {
                let cell = l[i];
                let qua = getQua(cell);
                if (!quaMap[qua]) {
                    quaMap[qua] = [];
                }
                quaMap[qua].push(cell);
            }
            for (let c in quaMap) {
                let arr = quaMap[c];
                arr = arr.sort(this.sortLv);
                let lvMaps = {};
                for (let i = 0; i < arr.length; i++) {
                    let cell = arr[i];
                    if (!lvMaps[cell.lv]) {
                        lvMaps[cell.lv] = [];
                    }
                    lvMaps[cell.lv].push(cell);
                }
                for (let v in lvMaps) {
                    let arrlv = lvMaps[v];
                    arrlv = arrlv.sort(this.sortStar);
                }
            }
            let _maxQua = Mount_ListProxy.Ins.maxQua;
            let a = [];
            for (let i = 1; i <= _maxQua; i++) {
                let m = quaMap[i];
                if (m) {
                    a.push(m);
                }
            }
            a = a.reverse();
            let b = [];
            for (let i = 0; i < a.length; i++) {
                b = b.concat(a[i]);
            }
            return b;
        }
    }

