    class GeXuQiPaoModel extends Laya.EventDispatcher {
        static get Ins() {
            if (!this._ins) {
                this._ins = new GeXuQiPaoModel();
            }
            return this._ins;
        }
        isDotMain() {
            if (this.isDotTask() || this.isDotLB()) {
                return true;
            }
            return false;
        }
        isDotTask() {
            if (!this.taskList) {
                return false;
            }
            for (let i = 0; i < this.taskList.length; i++) {
                if (this.taskList[i].state == 1) {
                    return true;
                }
            }
            return false;
        }
        isDotLB() {
            if (!this.packList) {
                return false;
            }
            for (let i = 0; i < this.packList.length; i++) {
                let cfg = RADrawEventPackProxy.Ins.GetDataById(this.packList[i].fid);
                if (cfg.f_PackType == 1) {
                    if (this.packList[i].count < cfg.f_PackBuyLimit) {
                        return true;
                    }
                }
            }
            return false;
        }
    }
    GeXuQiPaoModel.UPDATA_VIEW = "UPDATA_VIEW";
    GeXuQiPaoModel.UPDATA_XL_VIEW = "UPDATA_XL_VIEW";

    class GeXuQiPaoLBItem extends ui.views.gexuqipao.ui_gexuqipaoLBItemUI {
        constructor() {
            super();
            this.freeCtl = ButtonCtl.CreateBtn(this.freeBtn, this, this.onfreeBtnHandler);
            this.rateCtl = new RateBtn01Ctl(this.rate_btn, this, this.onfreeBtnHandler, ESkinRateBtn.Yellow);
        }
        onfreeBtnHandler() {
            if (this.cfg.f_PackPurchase == 0) {
                let req = new GeXuQiPaoPack_req;
                req.fid = this.cfg.f_id;
                SocketMgr.Ins.SendMessageBin(req);
            }
            else {
                ActivityModel.Ins.recharge(this.cfg.f_PackPurchase);
            }
        }
        setData(value) {
            this._data = value;
            this.cfg = RADrawEventPackProxy.Ins.GetDataById(value.fid);
            this.lab.text = this.cfg.f_PackName;
            ItemViewFactory.renderItemSlots(this.rewardCon, this.cfg.f_PackRewards, 10, 0.95, "left");
            let btn = this.freeCtl;
            this.rateCtl.visible = false;
            this.freeCtl.visible = false;
            let _freeIsShow = true;
            if (this.cfg.f_PackPurchase == 0) {
                this.tf3.text = E.getLang("Free");
            }
            else {
                let ppCfg = t_Purchase_PriceProxy.Ins.GetDataById(this.cfg.f_PackPurchase);
                if (ppCfg.f_isVoucher == EShopPayType.Voucher) {
                    btn = this.rateCtl.btnCtl;
                    this.rateCtl.cfg = ppCfg;
                    _freeIsShow = false;
                }
                this.tf3.text = StringUtil.moneyCv(ppCfg.f_price) + "元";
            }
            this.freeCtl.visible = _freeIsShow;
            this.rateCtl.btnCtl.visible = !this.freeCtl.visible;
            this.countTf.text = "限购:" + (this.cfg.f_PackBuyLimit - value.count) + "/" + this.cfg.f_PackBuyLimit;
            if (value.count >= this.cfg.f_PackBuyLimit) {
                btn.mouseEnable = false;
                btn.gray = true;
            }
            else {
                btn.mouseEnable = true;
                btn.gray = false;
            }
            DotManager.removeDot(btn.skin);
            if (this.cfg.f_PackPurchase == 0) {
                if (value.count < this.cfg.f_PackBuyLimit) {
                    DotManager.addDot(btn.skin);
                }
            }
        }
    }

    class GeXuQiPaoShopItem extends ui.views.gexuqipao.ui_gexuqipaoShopItemUI {
        constructor() {
            super();
            this.lab_num.visible = false;
            this.on(Laya.Event.CLICK, this, this.onClickHandler);
        }
        onClickHandler() {
            if (this._data) {
                let vo = GeXuQiPaoModel.Ins.shopList.find(ele => ele.fid == this._data.f_id);
                let num = 0;
                if (vo) {
                    num = vo.count;
                }
                if (num >= this._data.f_LimitedTimes) {
                    E.ViewMgr.ShowMidError("该物品已售罄");
                    return;
                }
                let arr = this._data.f_Price.split("-");
                let arr1 = this._data.f_ItemReward.split("-");
                MainModel.Ins.buy(parseInt(arr[0]), parseInt(arr[1]), parseInt(arr1[0]), parseInt(arr1[1]), new Laya.Handler(this, this.okBuyHandler));
            }
        }
        okBuyHandler() {
            if (this._data) {
                let req = new GeXuQiPaoShop_req;
                req.fid = this._data.f_id;
                req.count = 1;
                SocketMgr.Ins.SendMessageBin(req);
            }
        }
        setData(value) {
            if (!value)
                return;
            this._data = value;
            let voo = GeXuQiPaoModel.Ins.shopList.find(ele => ele.fid == value.f_id);
            let num = 0;
            if (voo) {
                num = voo.count;
            }
            this.lab_xg.text = "限购" + num + "/" + value.f_LimitedTimes;
            let vo = new ItemVo();
            vo.cfgId = parseInt(value.f_ItemReward.split("-")[0]);
            vo.count = parseInt(value.f_ItemReward.split("-")[1]);
            ItemViewFactory.refreshSlot(this.item, vo, false);
            this.lab_name.text = vo.getName();
            this.icon.skin = IconUtils.getIconByCfgId(parseInt(value.f_Price.split("-")[0]));
            this.lab.text = value.f_Price.split("-")[1];
        }
    }

    class GeXuQiPaoTaskItem extends ui.views.gexuqipao.ui_gexuqipaoTaskItemUI {
        constructor() {
            super();
            ButtonCtl.Create(this.btn, new Laya.Handler(this, this.onBtnClick));
            ButtonCtl.Create(this.btn1, new Laya.Handler(this, this.onBtn1Click));
        }
        onBtnClick() {
            if (this._cfg) {
                E.ViewMgr.Close(EViewType.GeXuQiPaoView);
                if (this._cfg.f_viewjump != 0) {
                    E.ViewMgr.OpenByFuncid(this._cfg.f_viewjump, false);
                }
            }
        }
        onBtn1Click() {
            if (this._data) {
                let req = new GeXuQiPaoTask_req;
                req.fid = this._data.fid;
                SocketMgr.Ins.SendMessageBin(req);
            }
        }
        setData(value) {
            if (!value)
                return;
            this._data = value;
            this._cfg = RADrawEventTaskProxy.Ins.GetDataById(value.fid);
            let stt;
            if (value.count >= this._cfg.f_TaskContent) {
                stt = this._cfg.f_TaskContent + "/" + this._cfg.f_TaskContent;
            }
            else {
                stt = value.count + "/" + this._cfg.f_TaskContent;
            }
            let st = StringUtil.format(t_Txt_Config.Ins.replace(this._cfg.f_Taskintro), this._cfg.f_TaskContent) + "(" + stt + ")";
            this.lab.text = t_Txt_Config.Ins.replace(st);
            ItemViewFactory.renderItemSlots(this.rewardCon, this._cfg.f_TaskRewards, 10, 0.95, "left");
            DotManager.removeDot(this.btn1);
            if (value.state == 2) {
                this.btn.visible = false;
                this.btn1.visible = true;
                this.btn1.mouseEnabled = false;
                this.btn1.skin = "remote/common/base/anniu_grey.png";
                this.lab2.text = "已领取";
            }
            else if (value.state == 1) {
                this.btn.visible = false;
                this.btn1.visible = true;
                this.btn1.mouseEnabled = true;
                this.btn1.skin = "remote/common/base/anniu_blue.png";
                this.lab2.text = "领取";
                DotManager.addDot(this.btn1, 10, -10);
            }
            else if (value.state == 0) {
                this.btn.visible = true;
                this.btn1.visible = false;
            }
        }
    }

