            if (this._eff1) {
                this._eff1.dispose();
                this._eff1 = null;
            }
            if (this._avatar) {
                this._avatar.dispose();
                this._avatar = null;
            }
            if (this._timeCtl) {
                this._timeCtl.stop();
            }
            MainModel.Ins.off(MainEvent.ValChangeCell, this, this.onValChange);
            GeXuQiPaoModel.Ins.off(GeXuQiPaoModel.UPDATA_XL_VIEW, this, this.onupdataXLView);
