            GuaJiModel.Ins.off(GuaJiModel.UPDATA_KUAISUVIEW, this, this.updataFree);
            this._timeCtl.stop();
            this._timeCtl1.stop();
            Laya.timer.clear(this, this.onTimer);
            for (let i = 1; i < 6; i++) {
                this["_timeCtl2" + i].clear(this, this.sendCmd);
            }
            this._timeCtl3.clear(this, this.sendCmd3);
