                this.UI = this._ui = new ui.views.jiedoufeng.ui_jiedoufengviewUI;
                this.bindClose(this._ui.btn_close);
                ButtonCtl.Create(this._ui.img_tq, new Laya.Handler(this, this.onBtnTQClick));
