            if (!this._eff) {
                this._eff = new SimpleEffect(this._ui.sp, `o/spine/succeed/shengli`);
            }
            this._eff.play(4, false, this, this.effEnd);
            this.updataView();
            Laya.timer.once(500, this, this.updataView1);
