    class SpringFestivalModel extends Laya.EventDispatcher {
        static get Ins() {
            if (!this._ins) {
                this._ins = new SpringFestivalModel();
            }
            return this._ins;
        }
        getIsEnroll(bo = true) {
            if (bo) {
                if (TimeUtil.serverTime > this.endunix) {
                    E.ViewMgr.ShowMidError("活动已结束");
                    return false;
                }
            }
            if (SpringFestivalModel.Ins.isEnroll == 0) {
                E.ViewMgr.ShowMidError("请先报名");
                return false;
            }
            return true;
        }
        isRedTip() {
            if (this.isEnrollRedTip() || this.isWWRedTip() || this.isPackRedTip() ||
                this.isTaskRedTip() || this.isRankRedTip()) {
                return true;
            }
            return false;
        }
        isEnrollRedTip() {
            if (TimeUtil.serverTime > this.endunix)
                return false;
            if (this.allianceId && this.canJoin && this.isEnroll == 0) {
                return true;
            }
            return false;
        }
        isWWRedTip() {
            if (!this.rewardList)
                return false;
            if (this.isEnroll == 0)
                return false;
            if (TimeUtil.serverTime > this.endunix)
                return false;
            for (let i = 0; i < this.rewardList.length; i++) {
                if (this.rewardList[i].state == 2) {
                    return true;
                }
            }
            return false;
        }
        isPackRedTip() {
            if (!this.packList)
                return false;
            if (this.isEnroll == 0)
                return false;
            if (TimeUtil.serverTime > this.endunix)
                return false;
            for (let i = 0; i < this.packList.length; i++) {
                let cfg = SFPackProxy.Ins.GetDataById(this.packList[i].fid);
                if (cfg.f_PackType == 1) {
                    if (this.packList[i].count < cfg.f_PackBuyLimit) {
                        return true;
                    }
                }
            }
            return false;
        }
        isTaskRedTip() {
            if (!this.taskList)
                return false;
            if (this.isEnroll == 0)
                return false;
            if (TimeUtil.serverTime > this.endunix)
                return false;
            for (let i = 0; i < this.taskList.length; i++) {
                if (this.taskList[i].state == 1) {
                    return true;
                }
            }
            return false;
        }
        isRankRedTip() {
            if (this.isEnroll == 0)
                return false;
            if (this.state == 2) {
                return true;
            }
            return false;
        }
    }
