            if (count >= this._cfg.f_taskcontent) {
                this.lab.text = this._cfg.f_taskcontent + "/" + this._cfg.f_taskcontent;
            }
            else {
                this.lab.text = count + "/" + this._cfg.f_taskcontent;
            }
